func auth(next http.Handler) http.Handler {           // shared behaviour
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !authorized(r) { http.Error(w, "unauthorized", 401); return }
		next.ServeHTTP(w, r)
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /orders/{id}", getOrder)      // dispatch table
	http.ListenAndServe(":8080", auth(logger(mux)))   // one entry point
}
